<?php
namespace App\Support;
use App\Models\{User,TutorGroup,TrainingSession,TimetableRoom as Room,TimetablePlan as Plan,TimetablePlanEntry as Entry,TimetableFlexibleDay as Day,TimetableCoverAllocation as Cover};
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;
use Carbon\Carbon;
class TimetableCover {
 private static function fields(Cover $c):array {return $c->only(['id','request_token','entry_id','original_staff_id','cover_staff_id','flexible_day_id','created_by']);}
 public static function intact(Cover $c):bool {try{return $c->source&&ReviewedImports::hash($c->source)===$c->source_hash&&$c->source['fields']===self::fields($c);}catch(\Throwable){return false;}}
 public static function basis(Entry $entry,Day $day,bool $lock=false,bool $future=true):array {
  $e=Entry::whereKey($entry->id)->when($lock,fn($q)=>$q->lockForUpdate())->firstOrFail();$p=Plan::whereKey($e->plan_id)->when($lock,fn($q)=>$q->lockForUpdate())->firstOrFail();$d=Day::whereKey($day->id)->when($lock,fn($q)=>$q->lockForUpdate())->firstOrFail();$cover=User::find($d->staff_id);$original=User::find($e->staff_id);$g=$e->group_id?TutorGroup::find($e->group_id):null;$room=$e->room_id?Room::find($e->room_id):null;
  if(!CentrePlanning::published($p)||$p->source['data']['timezone']!==config('app.timezone')||$p->state!=='Published'||$e->kind!=='Teaching'||!$cover||!$cover->active||$cover->role!=='tutor'||!$original||!$original->active||$original->role!=='tutor'||$cover->id===$original->id||!TimetableDuties::dayCurrent($d)||$d->work_date->toDateString()!==$e->work_date->toDateString()||$d->start_time>$e->start_time||$d->end_time<$e->end_time||!$g||!$g->active||$g->tutor_id!==$original->id||!$room||!$room->active||!CentrePlanning::roomIntact($room)){CentrePlanning::fail('Use an intact published Teaching occurrence, a different active Tutor and a current Flexible Duties Day covering the whole slot. Permanent group Tutor and register access remain unchanged.');}
  $row=collect($p->source['data']['rows'])->firstWhere('work_date',$e->work_date->toDateString());$members=\App\Models\Apprentice::where('tutor_group_id',$g->id)->orderBy('id')->pluck('id')->all();if(!$row||ReviewedImports::hash($g->getAttributes())!==$p->source['data']['group']['hash']||$members!==$row['members']||CentrePlanning::roomFields($room)!==$p->source['data']['room']['fields']||ReviewAppointments::seal($original)!==$p->source['data']['staff']['seal']||$room->capacity<$row['headcount']||!in_array('Teaching',$room->uses??[],true)||($future&&!Carbon::parse($row['work_date'].' '.$row['start_time'],$p->source['data']['timezone'])->gt(now()))){CentrePlanning::fail('Class source, room, membership or original Tutor changed. Reconcile the underlying published class first.');}
  $sessions=TrainingSession::where('tutor_group_id',$g->id)->whereDate('session_date',$row['work_date'])->where('state','!=','Cancelled')->where('start_time','<',$row['end_time'])->where('end_time','>',$row['start_time'])->orderBy('id')->when($lock,fn($q)=>$q->lockForUpdate())->get();$register=null;foreach($sessions as$s){if($e->training_session_id!==$s->id||!CentrePlanning::linkCurrent($e,$p)||$s->marks()->exists()||filled($s->delivered_learning)){CentrePlanning::fail('Link/reconcile the exact unmarked original register before planning cover. Cover grants no new register or apprentice access.');}$register=['id'=>$s->id,'hash'=>ReviewedImports::hash($s->getAttributes())];}
  return ['entry_id'=>$e->id,'plan_id'=>$p->id,'plan_version'=>$p->version,'plan_hash'=>$p->source_hash,'row'=>$row,'original_id'=>$original->id,'original_name'=>$original->name,'cover_id'=>$cover->id,'cover_name'=>$cover->name,'cover_seal'=>ReviewAppointments::seal($cover),'flexible_day_id'=>$d->id,'flexible_day_version'=>$d->version,'flexible_day_hash'=>$d->source_hash,'register'=>$register,'timezone'=>$p->source['data']['timezone']];
 }
 public static function active(Cover $c):bool {try{$v=$c->publication;return self::intact($c)&&$c->state==='Active'&&$c->active_entry_id===$c->entry_id&&$v&&$c->check_proof&&$v['version']===$c->version&&$v['source_hash']===$c->source_hash&&$v['check_hash']===ReviewedImports::hash($c->check_proof)&&$v['version']===$c->check_proof['version']+1;}catch(\Throwable){return false;}}
 public static function closed(Cover $c):bool {try{$x=$c->closure;return self::intact($c)&&$c->state==='Withdrawn'&&$c->active_entry_id===null&&$x&&$x['source_hash']===$c->source_hash&&$x['version']===$c->version&&$x['publication_hash']===ReviewedImports::hash($c->publication);}catch(\Throwable){return false;}}
 public static function current(Cover $c):bool {try{return self::active($c)&&$c->source['basis']===self::basis(Entry::findOrFail($c->entry_id),Day::findOrFail($c->flexible_day_id),false,false);}catch(\Throwable){return false;}}
 public static function overlay(array $busy,array $dates):array {
  $covers=Cover::where(fn($q)=>$q->where('state','Active')->orWhereNotNull('publication'))->orderBy('id')->get();foreach($covers as$c){if(self::intact($c)&&!in_array($c->source['basis']['row']['work_date'],$dates,true)){continue;}if(self::closed($c)){continue;}if(!self::active($c)){$busy['uncertain'][]='Cover evidence needs a planner check: '.$c->id;continue;}$b=$c->source['basis'];$row=$b['row'];if($dates&&!in_array($row['work_date'],$dates,true)){continue;}$key='p'.$b['plan_id'].':'.$row['work_date'];$index=null;foreach($busy['rows']as$i=>$r){if($r['key']===$key){$index=$i;break;}}if($index!==null&&self::current($c)){$busy['rows'][$index]['original_staff_id']=$c->original_staff_id;$busy['rows'][$index]['staff_id']=$c->cover_staff_id;$busy['rows'][$index]['cover_id']=$c->id;$busy['rows'][$index]['cover_current']=true;$busy['rows'][$index]['stale']=false;}else{if($index!==null){$busy['rows'][$index]['stale']=true;}$busy['rows'][]=$row+['key'=>'c'.$c->id,'plan_id'=>null,'external'=>false,'stale'=>true,'cover_id'=>$c->id,'cover_current'=>false];$last=array_key_last($busy['rows']);$busy['rows'][$last]['staff_id']=$c->cover_staff_id;$busy['rows'][$last]['room_id']=null;$busy['rows'][$last]['group_id']=null;$busy['rows'][$last]['members']=[];$busy['rows'][$last]['kind']='Cover hold';$busy['rows'][$last]['title']='Cover source needs checking';}}
  return $busy;
 }
 public static function inspect(Cover $c,bool $lock=false):array {
  if(!self::intact($c)){return ['errors'=>['Cover evidence needs repair'],'fingerprint'=>null];}try{$b=self::basis(Entry::findOrFail($c->entry_id),Day::findOrFail($c->flexible_day_id),$lock);if($b!==$c->source['basis']){CentrePlanning::fail('Cover source changed. Prepare a new proposal.');}}catch(\Throwable $e){return ['errors'=>['Current class / Flexible Duties Day source needs checking. Prepare a new proposal after reconciling it.'],'fingerprint'=>null];}
  $busy=CentrePlanning::busy([$b['row']['work_date']],null,$lock);$errors=$busy['uncertain'];$row=$b['row'];$row['staff_id']=$c->cover_staff_id;$key='p'.$b['plan_id'].':'.$row['work_date'];foreach($busy['rows']as$other){if($other['key']===$key||($other['cover_id']??null)===$c->id){continue;}if(CentrePlanning::overlap($row,$other)&&CentrePlanning::shared($row,$other)){$errors[]='Cover conflicts with existing staff, room, group or learner planning.';}}
  $physical=array_values(array_filter($busy['rows'],fn($r)=>$r['staff_id']===$c->cover_staff_id&&in_array($r['site'],['Doncaster','Sheffield'],true)&&$r['key']!==$key&&($r['cover_id']??null)!==$c->id));foreach($physical as$other){if($other['site']!==$row['site']){$errors[]='This cover allocation would cross centres on the same day; use the separate travel-aware planning process instead.';}}
  if(Cover::where('active_entry_id',$c->entry_id)->where('id','!=',$c->id)->exists()){$errors[]='Another active cover allocation exists for this occurrence.';}
  return ['errors'=>array_values(array_unique($errors)),'fingerprint'=>ReviewedImports::hash($busy)];
 }
 public static function prepare(User $actor,int $auth,Entry $entry,Day $day,string $token,string $reference):Cover {
  if(!Str::isUuid($token)||trim($reference)===''||mb_strlen($reference)>1000){CentrePlanning::fail('Use a fresh request and a safe manager suitability/cover reference.');}return DB::transaction(function()use($actor,$auth,$entry,$day,$token,$reference):Cover {User::whereIn('id',[$actor->id,$entry->staff_id,$day->staff_id])->orderBy('id')->lockForUpdate()->get();$u=CentrePlanning::actor($actor,$auth);$b=self::basis($entry,$day,true);if($old=Cover::where('request_token',$token)->first()){if(self::intact($old)&&$old->created_by===$u->id&&$old->source['basis']===$b&&$old->source['reference']===trim($reference)){return $old;}CentrePlanning::fail('Request already used for different source.');}$c=new Cover(['id'=>(string)Str::uuid(),'request_token'=>$token,'entry_id'=>$entry->id,'original_staff_id'=>$entry->staff_id,'cover_staff_id'=>$day->staff_id,'flexible_day_id'=>$day->id,'created_by'=>$u->id,'state'=>'Draft','version'=>1]);$c->source=['fields'=>self::fields($c),'basis'=>$b,'reference'=>trim($reference),'prepared_auth'=>$u->auth_version,'register_access_granted'=>false];$c->source_hash=ReviewedImports::hash($c->source);$c->save();TimetableDuties::event($u,'cover_prepared','cover',$c->id,1,['source_hash'=>$c->source_hash]);return $c;},3);
 }
 public static function check(User $actor,int $auth,Cover $record,int $version):void {DB::transaction(function()use($actor,$auth,$record,$version):void {$u=CentrePlanning::actor($actor,$auth);$c=Cover::whereKey($record->id)->lockForUpdate()->firstOrFail();if($c->state!=='Draft'||$c->version!==$version){CentrePlanning::fail();}$r=self::inspect($c,true);if($r['errors']){CentrePlanning::fail(implode(' ',$r['errors']));}$c->version++;$c->check_proof=['version'=>$c->version,'source_hash'=>$c->source_hash,'fingerprint'=>$r['fingerprint'],'by'=>$u->id,'auth'=>$u->auth_version,'at'=>now()->toIso8601String()];$c->save();TimetableDuties::event($u,'cover_checked','cover',$c->id,$c->version,['source_hash'=>$c->source_hash]);},3);}
 public static function publish(User $actor,int $auth,Cover $record,int $version):void {DB::transaction(function()use($actor,$auth,$record,$version):void {User::whereIn('id',[$actor->id,$record->original_staff_id,$record->cover_staff_id])->orderBy('id')->lockForUpdate()->get();$u=CentrePlanning::actor($actor,$auth);Entry::whereKey($record->entry_id)->lockForUpdate()->firstOrFail();$c=Cover::whereKey($record->id)->lockForUpdate()->firstOrFail();if($c->state!=='Draft'||$c->version!==$version||!self::intact($c)||!$c->check_proof||$c->check_proof['version']!==$version||$c->check_proof['source_hash']!==$c->source_hash){CentrePlanning::fail('Check the current cover proposal before publication.');}$checker=User::find($c->check_proof['by']);if(!$checker||!CentrePlanning::allowed($checker)||$checker->auth_version!==$c->check_proof['auth']){CentrePlanning::fail('Checker authority changed.');}$r=self::inspect($c,true);if($r['errors']||$r['fingerprint']!==$c->check_proof['fingerprint']){CentrePlanning::fail('Cover timetable changed. Check again.');}$c->version++;$c->state='Active';$c->active_entry_id=$c->entry_id;$c->publication=['version'=>$c->version,'source_hash'=>$c->source_hash,'check_hash'=>ReviewedImports::hash($c->check_proof),'by'=>$u->id,'at'=>now()->toIso8601String()];$c->save();TimetableDuties::event($u,'cover_published','cover',$c->id,$c->version,['source_hash'=>$c->source_hash,'register_access_granted'=>false]);},3);}
 public static function withdraw(User $actor,int $auth,Cover $record,int $version,string $reason):void {DB::transaction(function()use($actor,$auth,$record,$version,$reason):void {$u=CentrePlanning::actor($actor,$auth);$c=Cover::whereKey($record->id)->lockForUpdate()->firstOrFail();if(!self::intact($c)||$c->version!==$version||!in_array($c->state,['Draft','Active'],true)||!filled($reason)||!Carbon::parse($c->source['basis']['row']['work_date'].' '.$c->source['basis']['row']['start_time'],$c->source['basis']['timezone'])->gt(now())){CentrePlanning::fail('Withdraw only current future cover planning.');}$c->version++;$c->state='Withdrawn';$c->active_entry_id=null;$c->closure=['version'=>$c->version,'source_hash'=>$c->source_hash,'publication_hash'=>ReviewedImports::hash($c->publication),'by'=>$u->id,'reason'=>$reason,'at'=>now()->toIso8601String()];$c->save();TimetableDuties::event($u,'cover_withdrawn','cover',$c->id,$c->version,['reason'=>$reason,'register_unchanged'=>true]);},3);}
}
